<?php
require __DIR__.'/base.php';$id=autenticado();exigir_post();$sol=(int)($_POST['id_solicitacao']??0);$nota=(int)($_POST['nota']??0);$coment=trim($_POST['comentario']??'');if($sol<1||$nota<1||$nota>5||mb_strlen($coment)>300)responder('nok','Informe uma nota de 1 a 5 e comentário de até 300 caracteres.');
$db=banco();$stmt=$db->prepare("SELECT s.id_usuario_solicitante,i.id_usuario_publicador FROM solicitacao s JOIN solicitacao_item si ON si.id_solicitacao=s.id_solicitacao JOIN item i ON i.id_item=si.id_item WHERE s.id_solicitacao=? AND s.status_soli='Concluída'");$stmt->bind_param('i',$sol);$stmt->execute();$r=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$r||!in_array($id,[(int)$r['id_usuario_solicitante'],(int)$r['id_usuario_publicador']],true))responder('nok','Doação concluída não encontrada.');$outro=$id===(int)$r['id_usuario_solicitante']?(int)$r['id_usuario_publicador']:(int)$r['id_usuario_solicitante'];$stmt=$db->prepare('SELECT id_avaliacao FROM avaliacao WHERE id_solicitacao=? AND id_usuario_avaliador=?');$stmt->bind_param('ii',$sol,$id);$stmt->execute();$ja=$stmt->get_result()->num_rows;$stmt->close();if($ja)responder('nok','Você já avaliou esta pessoa nesta doação.');$stmt=$db->prepare('INSERT INTO avaliacao(nota,comentario,data_avaliacao,id_usuario_avaliador,id_usuario_avaliado,id_solicitacao) VALUES (?,?,CURDATE(),?,?,?)');$stmt->bind_param('isiii',$nota,$coment,$id,$outro,$sol);$stmt->execute();$stmt->close();responder('ok','Avaliação registrada.');
